package ru.secondmemory;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class ConversationAnalysisTest {
 @Rule public TemporaryFolder folder=new TemporaryFolder();
 private final List<ConversationAnalysis.Line> lines=Arrays.asList(new ConversationAnalysis.Line(1,"18:00:00","В больнице закончилась бумага для принтера.",1000),new ConversationAnalysis.Line(2,"18:00:10","Решили заказать бумагу в понедельник.",2000));
 private JSONObject item(String kind,String text,int line,String quote)throws Exception{return new JSONObject().put("kind",kind).put("text",text).put("owner","").put("line",line).put("quote",quote);}
 private String wrap(JSONObject item)throws Exception{return new JSONObject().put("items",new JSONArray().put(item)).toString();}
 @Test public void keepsNonTaskFactsAndDecisionsWithSource()throws Exception{JSONArray points=ConversationAnalysis.parse(wrap(item("fact","Закончилась бумага",1,"закончилась бумага для принтера")),lines);assertEquals("fact",points.getJSONObject(0).getString("kind"));assertEquals("18:00:00",points.getJSONObject(0).getString("time"));assertTrue(ConversationAnalysis.prompt(lines).contains("ВСЕ разговоры"));assertTrue(ConversationAnalysis.prompt(lines).contains(lines.get(1).text));}
 @Test public void refusesInventedSourcesAndNumbers()throws Exception{for(JSONObject wrong:Arrays.asList(item("decision","Решили заказать бумагу",99,"Решили заказать бумагу"),item("fact","Бумагу доставят 12 ноября",1,"закончилась бумага"),item("fact","Бумага закончилась",1,"будет доставлена завтра"))){try{ConversationAnalysis.parse(wrap(wrong),lines);fail();}catch(JSONException expected){}}}
 @Test public void doesNotGuessOwner()throws Exception{JSONObject p=item("fact","Закончилась бумага",1,"закончилась бумага").put("owner","Олег");assertEquals("",ConversationAnalysis.parse(wrap(p),lines).getJSONObject(0).getString("owner"));}
 @Test public void longConversationsHaveNoSkippedTextAndResume()throws Exception{File dir=folder.newFolder();String text=String.join(" ",Collections.nCopies(1600,"разговор"));try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(dir,"transcript.jsonl")),StandardCharsets.UTF_8)){out.write(new JSONObject().put("text",text).put("saved_at","12:00:00").toString()+"\n");}List<ConversationAnalysis.Line> all=ConversationAnalysis.read(dir);StringBuilder reconstructed=new StringBuilder();int cursor=0,count=0;while(true){List<ConversationAnalysis.Line> batch=ConversationAnalysis.batch(all,cursor);if(batch.isEmpty())break;for(ConversationAnalysis.Line l:batch){assertTrue(l.id>cursor);reconstructed.append(l.text).append(' ');count++;}cursor=batch.get(batch.size()-1).id;}assertEquals(text,reconstructed.toString().trim());assertEquals(all.size(),count);JSONObject state=new JSONObject().put("cursor",cursor).put("items",new JSONArray());ConversationAnalysis.save(dir,state);assertEquals(cursor,ConversationAnalysis.load(dir).getInt("cursor"));assertTrue(ConversationAnalysis.batch(all,cursor).isEmpty());}
 @Test public void rendersEvidenceAndOpenQuestions()throws Exception{JSONArray points=ConversationAnalysis.parse(wrap(item("decision","Заказать бумагу",2,"Решили заказать бумагу в понедельник")),lines);String s=ConversationAnalysis.render("test",new JSONObject().put("cursor",2).put("items",points));assertTrue(s.contains("Решения"));assertTrue(s.contains("18:00:10"));assertTrue(s.contains("Решили заказать бумагу в понедельник"));}
}
